import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"脉冲能量与重复频率","description":"","frontmatter":{"title":"脉冲能量与重复频率","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pulse-energy-rep-rate.md","filePath":"litho/pulse-energy-rep-rate.md","lastUpdated":1789023840000}'),E={name:"litho/pulse-energy-rep-rate.md"};function _(c,a,f,u,m,D){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="脉冲能量与重复频率" tabindex="-1">脉冲能量与重复频率 <a class="header-anchor" href="#脉冲能量与重复频率" aria-label="Permalink to &quot;脉冲能量与重复频率&quot;">​</a></h1><div class="epigraph"><p>剂量是脉冲能量乘脉冲数；产能是重复频率乘扫描时间。两个数不能合成一个「激光功率」就结束。</p><footer>—— 对照 [剂量控制](/litho/dose-control)、[扫描仪产能](/litho/scanner-throughput)</footer></div><p><a href="/litho/laser-linewidth-narrowing">上一课</a>钉住带宽。缺口是能量怎么变成晶圆上的 mJ/cm²：单脉冲能量 \\(E_p\\) 与重复频率 \\(f\\)。本课拆开这两项，不重写剂量传感器硬件（后课闭环）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平均功率 \\(P=E_p f\\) 看起来够用，扫描时狭缝只看见有限脉冲数。\\(f\\) 低则一场里脉冲少，剂量量化粗、斑纹平均差；\\(E_p\\) 高则光学损伤与气体负担升。把「光源功率」写成一个广告数字，无法解释为何高剂量层要降速或加脉冲。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>剂量 \\(D \\propto N E_p \\times\\) 照明透过率。扫描速度提高，\\(N\\) 下降，必须升 \\(f\\) 或升 \\(E_p\\) 或加 <a href="/litho/focus-drilling">focus drilling</a> 类的多次。脉冲能量稳定度进 CDU：脉冲间抖动直接是剂量噪声。本课只要求把 \\(E_p\\) 与 \\(f\\) 分列监控。</p>',7)),(e(),n(h,null,{default:r(()=>[d(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20EP%5B%22%E5%8D%95%E8%84%89%E5%86%B2%E8%83%BD%E9%87%8F%22%5D%20--%3E%20DOSE%5B%22%E5%9C%BA%E5%89%82%E9%87%8F%22%5D%0A%20%20F%5B%22%E9%87%8D%E5%A4%8D%E9%A2%91%E7%8E%87%22%5D%20--%3E%20N%5B%22%E7%8B%AD%E7%BC%9D%E5%86%85%E8%84%89%E5%86%B2%E6%95%B0%22%5D%0A%20%20N%20--%3E%20DOSE%0A%20%20F%20--%3E%20TPUT%5B%22%E6%89%AB%E6%8F%8F%E4%BA%A7%E8%83%BD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">浸没头与工件台加速度限制扫描速度时，再升 \\(f\\) 也灌不进更多脉冲——产能瓶颈会从激光挪到台。见后课工件台。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个脉冲在胶里是一次曝光增量。CAR 积分这些增量；若脉冲间隔与淬灭/扩散时间尺度相近，理论上有脉冲结构效应，量产上通常仍当剂量积分。损伤：高 \\(E_p\\) 打镜头镀膜与 CaF₂。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课气体寿命：维持 \\(E_p\\) 的成本。剂量闭环硬件再后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剂量看 \\(E_p\\times N\\)，产能看 \\(f\\) 与扫描。</li><li>脉冲抖动是剂量噪声，不是「平均功率不够」。</li><li>出处：剂量与产能课；准分子运行通识。</li></ul>',7))])}const T=l(E,[["render",_]]);export{B as __pageData,T as default};
